from dataclasses import dataclass


@dataclass
class Entry:
    ts: str
    channel: int
    text: str


def parse_line(line: str) -> Entry:
    parts = line.split(" | ")
    if len(parts) != 3:
        raise ValueError(f"malformed line: {line!r}")
    ts, channel_part, text = parts
    if not channel_part.startswith("ch "):
        raise ValueError(f"malformed channel: {channel_part!r}")
    try:
        channel = int(channel_part[len("ch "):])
    except ValueError:
        raise ValueError(f"malformed channel: {channel_part!r}") from None
    return Entry(ts=ts, channel=channel, text=text)

from collections import Counter


def summarise(entries) -> dict:
    per_channel = Counter(entry.channel for entry in entries)
    return {"total": sum(per_channel.values()), "per_channel": dict(per_channel)}

from harborlog import Entry, summarise


def test_summarise():
    entries = [
        Entry(ts="2026-11-02T22:00:00Z", channel=16, text="hello harbour"),
        Entry(ts="2026-11-02T22:01:00Z", channel=16, text="again"),
        Entry(ts="2026-11-02T22:02:00Z", channel=9, text="other channel"),
    ]
    assert summarise(entries) == {"total": 3, "per_channel": {16: 2, 9: 1}}

